Lemma lit_facts : forall S l (m : mem), In (S, l) LEPT_LITS -> mem_inv asegs m ->
  exists str slack : list byte, bytes_at asegs m S (str ++ Z_to_bv 8 0 :: slack) /\ ~ In (Z_to_bv 8 0) str
